// Decide se a mensagem que chegou merece atenção, antes de qualquer consulta ao banco.
// Toda saída tem o campo "atender" e, quando é false, o "motivo" — nada some sem explicação.
const cfg = $input.first().json;
const body = $('Webhook · Evolution API').first().json.body || {};
const d = body.data || {};
const key = d.key || {};
const jid = key.remoteJid || '';
const texto = (d.message?.conversation || '').trim();
const idadeS = d.messageTimestamp ? Math.round(Date.now() / 1000 - Number(d.messageTimestamp)) : null;
const conversaPropria = !!body.sender && jid === body.sender;

let motivo = null;
if (body.event !== 'messages.upsert') motivo = 'evento que não é mensagem nova';
else if (jid.endsWith('@g.us')) motivo = 'mensagem de grupo';
else if (jid.endsWith('@broadcast')) motivo = 'status/lista de transmissão';
else if (jid.endsWith('@lid')) motivo = 'contato sem número resolvido (@lid)';
else if (!texto) motivo = 'sem texto (mídia, figurinha, áudio)';
else if (idadeS !== null && idadeS > cfg.idade_maxima_s) motivo = 'mensagem antiga (' + idadeS + 's) — sincronização de histórico';
else if (key.fromMe) {
  // Mensagem enviada pelo próprio número. Só vale no modo de teste, na conversa
  // "Você", e só se foi digitada no celular. A resposta da IA sai pela Evolution
  // com origem "web" — é essa diferença que impede a IA de responder a si mesma.
  const doCelular = ['android', 'ios'].includes(d.source);
  if (!(cfg.modo_teste_conversa_propria && conversaPropria && doCelular)) motivo = 'enviada pelo próprio número';
}

return [{
  json: {
    atender: motivo === null,
    motivo,
    wa_message_id: key.id || null,
    wa_id: jid.split('@')[0],
    nome_contato: d.pushName || null,
    texto,
    conversa_propria: conversaPropria,
    origem: d.source || null,
  },
}];

// Junta o resultado do banco com a mensagem e decide se a IA responde.
// A consulta anterior sempre devolve exatamente uma linha (ver o SQL), então
// "nenhuma linha" nunca acontece aqui — a falha silenciosa do workflow 01 não se repete.
const msg = $('Normalizar mensagem').first().json;
const r = $input.first().json;

let motivo = null;
if (!r.permitido) motivo = 'contato fora da lista de atendimento';
else if (!r.registro_id) motivo = 'mensagem repetida (webhook reentregue)';
else if (r.humano_desde) motivo = 'conversa com humano desde ' + r.humano_desde;

return [{ json: { ...msg, registro_id: r.registro_id, monday_item_id: r.monday_item_id, responder: motivo === null, motivo } }];

// Transforma a decisão da IA no que o resto do workflow precisa: texto final,
// pausa de digitação e os valores das colunas do Monday.
const cfg = $('Configuração').first().json;
const msg = $('Decidir se responde').first().json;
// A IA devolve JSON (modo json_object), mas quem valida é este nó — não o parser do
// próprio agente, que recusava a resposta inteira por um campo fora da lista.
// Campo inválido vira um valor seguro; JSON ilegível vira passagem para humano.
const INTENCOES = ['Dúvida', 'Orçamento', 'Suporte', 'Reclamação', 'Outro'];
const STATUS = ['Em conversa', 'Qualificado', 'Não qualificado', 'Encerrado'];
let ia;
let falhaFormato = false;
try {
  const bruto = $input.first().json.output;
  ia = typeof bruto === 'string' ? JSON.parse(bruto) : bruto;
  if (!ia || typeof ia !== 'object') throw new Error('saída vazia');
} catch (e) {
  falhaFormato = true;
  ia = { precisa_humano: true, motivo_humano: 'resposta da IA ilegível: ' + e.message };
}
if (!INTENCOES.includes(ia.intencao)) ia.intencao = 'Outro';
if (!STATUS.includes(ia.status)) ia.status = 'Em conversa';

const precisaHumano = ia.precisa_humano === true || falhaFormato;
const status = precisaHumano ? 'Aguardando humano' : ia.status;
const resposta = (ia.resposta || '').trim()
  || 'Obrigado pela mensagem! Vou passar para alguém da equipe, que já te responde por aqui.';

// Pausa proporcional ao tamanho: ~45 ms por caractere, entre 2 e 12 segundos.
// Responder em 200 ms um texto de três linhas é o sinal mais claro de robô.
const delay = Math.min(12000, Math.max(2000, 1500 + resposta.length * 45));

const agora = new Date().toISOString();
const colunas = {
  telefone: { phone: msg.wa_id, countryShortName: 'BR' },
  wa_id: msg.wa_id,
  status: { label: status },
  intencao: { label: ia.intencao },
  resumo: { text: ia.resumo || '' },
  mensagem_recente: { text: msg.texto },
  atualizado_em: { date: agora.slice(0, 10), time: agora.slice(11, 19) },
};
const nomeItem = (ia.nome_cliente || msg.nome_contato || msg.wa_id).slice(0, 80);
const boardId = String(cfg.monday_board_id);

return [{
  json: {
    ...msg,
    resposta,
    delay,
    precisa_humano: precisaHumano,
    motivo_humano: ia.motivo_humano || null,
    intencao: ia.intencao,
    status,
    nome_cliente: ia.nome_cliente || '',
    monday_criar: {
      query: 'mutation ($board: ID!, $nome: String!, $cols: JSON!) { create_item (board_id: $board, item_name: $nome, column_values: $cols) { id } }',
      variables: { board: boardId, nome: nomeItem, cols: JSON.stringify(colunas) },
    },
    monday_atualizar: {
      query: 'mutation ($board: ID!, $item: ID!, $cols: JSON!) { change_multiple_column_values (board_id: $board, item_id: $item, column_values: $cols) { id } }',
      variables: { board: boardId, item: String(msg.monday_item_id || ''), cols: JSON.stringify(colunas) },
    },
  },
}];

// O Monday (GraphQL) responde erro com HTTP 200 e a mensagem dentro do corpo —
// o nó HTTP trata isso como sucesso. Sem este nó, o lead deixava de ser gravado
// com a execução verde. Aqui o erro vira erro de verdade.
const r = $input.first().json;
if (r.errors?.length || !r.data?.create_item?.id) {
  throw new Error('Monday recusou a criação do lead: ' + (r.errors || []).map((e) => e.message).join(' | '));
}
return [{ json: { monday_item_id: r.data.create_item.id } }];
